import { createCanvassingAppCanvasser } from '~/client';
import type { AppCanvasserSelectorListItem, CreateAppCanvasserRequest } from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useCreateCanvassingAppCanvasser = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (params: { data: CreateAppCanvasserRequest }): Promise<AppCanvasserSelectorListItem> =>
      createCanvassingAppCanvasser({
        composable: '$fetch',
        body: ref(params.data),
      }),
    onSuccess: () => {
      queryCache.invalidateQueries({ key: ['selector-canvasser-list'] });
      showToastSuccess('Canvasser created successfully');
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    createCanvassingAppCanvasser: mutateAsync,
    isCreatingCanvassingAppCanvasser: computed(() => asyncStatus.value === 'loading'),
  };
});
