<template>
  <Dialog v-model:open="isOpen" @update:open="onOpenUpdate">
    <DialogTrigger as-child>
      <slot />
    </DialogTrigger>
    <DialogContent class="gap-6">
      <DialogHeader>
        <DialogTitle>Create New Canvasser Entry</DialogTitle>
        <DialogDescription>
          Add a canvasser that exists in the canvassing app but is not in the list yet.
        </DialogDescription>
      </DialogHeader>
      <form id="createCanvassingAppCanvasser" class="grid grid-cols-2 gap-4" @submit.prevent="onSubmit">
        <FormItemWrapper name="first_name" label="First Name" is-required item-class="col-span-2 md:col-span-1">
          <template #default="{ slots }">
            <Input
              id="canvassing-app-canvasser-first-name"
              data-testid="canvassing-app-canvasser-first-name-input"
              type="text"
              placeholder="John"
              v-bind="slots.componentField"
              :disabled="isCreatingCanvassingAppCanvasser"
            />
          </template>
        </FormItemWrapper>
        <FormItemWrapper name="last_name" label="Last Name" is-required item-class="col-span-2 md:col-span-1">
          <template #default="{ slots }">
            <Input
              id="canvassing-app-canvasser-last-name"
              data-testid="canvassing-app-canvasser-last-name-input"
              type="text"
              placeholder="Doe"
              v-bind="slots.componentField"
              :disabled="isCreatingCanvassingAppCanvasser"
            />
          </template>
        </FormItemWrapper>
        <FormItemWrapper name="email" label="Username" is-required item-class="col-span-2">
          <template #default="{ slots }">
            <Input
              id="canvassing-app-canvasser-username"
              data-testid="canvassing-app-canvasser-username-input"
              type="text"
              placeholder="user@example.com or username"
              v-bind="slots.componentField"
              :disabled="isCreatingCanvassingAppCanvasser"
            />
          </template>
        </FormItemWrapper>
      </form>
      <DialogFooter class="flex flex-row justify-end gap-2">
        <DialogClose as-child>
          <Button variant="outline" class="h-10 px-4" :disabled="isCreatingCanvassingAppCanvasser">Cancel</Button>
        </DialogClose>
        <Button
          type="submit"
          form="createCanvassingAppCanvasser"
          data-testid="canvassing-app-canvasser-submit"
          :loading="isCreatingCanvassingAppCanvasser"
        >
          Add
        </Button>
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { toTypedSchema } from '@vee-validate/zod';
import { useForm } from 'vee-validate';
import type { AppCanvasserSelectorListItem } from '~/client';
import { canvassingAppCanvasserCreateSchema } from '~/constants/validationSchemas/canvassingAppCanvasserCreate';
import { useCreateCanvassingAppCanvasser } from '~/mutations/assignments/createCanvassingAppCanvasser';

const props = defineProps<{
  projectId: string;
}>();

const emit = defineEmits<{
  created: [item: AppCanvasserSelectorListItem];
}>();

const isOpen = ref<boolean>(false);

const { createCanvassingAppCanvasser, isCreatingCanvassingAppCanvasser } = useCreateCanvassingAppCanvasser();

const { handleSubmit, resetForm } = useForm({
  validationSchema: toTypedSchema(canvassingAppCanvasserCreateSchema),
});

const onSubmit = handleSubmit(async (values) => {
  const item = await createCanvassingAppCanvasser({
    data: {
      project_id: props.projectId,
      first_name: values.first_name,
      last_name: values.last_name,
      email: values.email,
    },
  });
  emit('created', item);
  isOpen.value = false;
});

function onOpenUpdate(open: boolean) {
  if (!open) resetForm();
}
</script>
