import * as z from 'zod';

export const canvassingAppCanvasserCreateSchema = z.object({
  first_name: z
    .string({ message: 'First Name is required' })
    .trim()
    .min(1, { message: 'First Name is required' })
    .max(255, { message: 'First Name cannot exceed 255 characters' }),
  last_name: z
    .string({ message: 'Last Name is required' })
    .trim()
    .min(1, { message: 'Last Name is required' })
    .max(255, { message: 'Last Name cannot exceed 255 characters' }),
  email: z
    .string({ message: 'Username is required' })
    .trim()
    .min(3, { message: 'Username must be at least 3 characters' })
    .max(255, { message: 'Username cannot exceed 255 characters' }),
});

export type CanvassingAppCanvasserCreateInput = z.input<typeof canvassingAppCanvasserCreateSchema>;
export type CanvassingAppCanvasserCreateOutput = z.output<typeof canvassingAppCanvasserCreateSchema>;
